/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Theme } from 'app/features/template/theme/model/theme.model';
import { ThemeRepository } from 'app/features/template/theme/repository/theme-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'theme-view-disable-selection-action', standalone: false, template: '' })
export class ThemeViewDisableSelectionActionComponent extends ConfirmSelectionAction<Theme> {
  readonly name = 'disableSelection';
  protected readonly scope = 'template/theme';
  protected readonly repository = inject(ThemeRepository);

  protected override appliesTo(items: Theme[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: Theme[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
